<?php
/**
 * Transparent proxy: streams a media file from the storage under its original uploads address.
 *
 * proxy.php loads this class without WordPress when uploads/.htaccess rewrites a request for a
 * missing file, and the plugin uses it as the fallback inside WordPress on servers without
 * .htaccess. It therefore relies on plain PHP only and reads its settings from a generated file
 * that contains no credentials: the storage address, the site folder and the uploads location.
 */

if ( ! defined( 'ABSPATH' ) && ! defined( 'SIMPLE_STORAGE_PROXY' ) ) {
	exit;
}

final class Simple_Storage_Proxy {
	public const CONFIG_VERSION = 1;
	public const CONFIG_MARKER = 'Generated by Simple Storage';

	/**
	 * Files a web server can run, in any position of a name ("shell.php.jpg"): they are never
	 * served from the storage and never travel in either direction.
	 */
	public const CODE_EXTENSIONS = array( 'php', 'php3', 'php4', 'php5', 'php7', 'php8', 'phtml', 'pht', 'phar', 'phps', 'shtml', 'cgi' );

	/** Redirects of the storage followed for one file. */
	private const MAX_REDIRECTS = 2;

	/** Types a browser opens safely under the site address; anything else is a download. */
	private const TYPES = array(
		'jpg'  => 'image/jpeg',
		'jpeg' => 'image/jpeg',
		'jpe'  => 'image/jpeg',
		'png'  => 'image/png',
		'gif'  => 'image/gif',
		'webp' => 'image/webp',
		'avif' => 'image/avif',
		'heic' => 'image/heic',
		'heif' => 'image/heif',
		'jxl'  => 'image/jxl',
		'svg'  => 'image/svg+xml',
		'ico'  => 'image/x-icon',
		'bmp'  => 'image/bmp',
		'tif'  => 'image/tiff',
		'tiff' => 'image/tiff',
		'mp4'  => 'video/mp4',
		'm4v'  => 'video/mp4',
		'mov'  => 'video/quicktime',
		'webm' => 'video/webm',
		'ogv'  => 'video/ogg',
		'mkv'  => 'video/x-matroska',
		'avi'  => 'video/x-msvideo',
		'wmv'  => 'video/x-ms-wmv',
		'mpg'  => 'video/mpeg',
		'mpeg' => 'video/mpeg',
		'3gp'  => 'video/3gpp',
		'ts'   => 'video/mp2t',
		'm3u8' => 'application/vnd.apple.mpegurl',
		'mp3'  => 'audio/mpeg',
		'm4a'  => 'audio/mp4',
		'ogg'  => 'audio/ogg',
		'oga'  => 'audio/ogg',
		'wav'  => 'audio/wav',
		'flac' => 'audio/flac',
		'aac'  => 'audio/aac',
		'opus' => 'audio/opus',
		'pdf'  => 'application/pdf',
		'txt'  => 'text/plain; charset=utf-8',
		'vtt'  => 'text/vtt; charset=utf-8',
		'csv'  => 'text/csv; charset=utf-8',
		'json' => 'application/json',
		'zip'  => 'application/zip',
		'doc'  => 'application/msword',
		'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
		'xls'  => 'application/vnd.ms-excel',
		'xlsx' => 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
		'ppt'  => 'application/vnd.ms-powerpoint',
		'pptx' => 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
		'rtf'  => 'application/rtf',
		'odt'  => 'application/vnd.oasis.opendocument.text',
		'ods'  => 'application/vnd.oasis.opendocument.spreadsheet',
		'odp'  => 'application/vnd.oasis.opendocument.presentation',
		'epub' => 'application/epub+zip',
		'gz'   => 'application/gzip',
		'rar'  => 'application/vnd.rar',
		'7z'   => 'application/x-7z-compressed',
		'tar'  => 'application/x-tar',
		'woff' => 'font/woff',
		'woff2' => 'font/woff2',
		'ttf'  => 'font/ttf',
		'otf'  => 'font/otf',
	);

	/** Where the generated configuration lives: next to the plugins folder, as wp-content usually is. */
	public static function config_file(): string {
		return dirname( __DIR__, 3 ) . '/simple-storage-config.php';
	}

	/** @return array<string, mixed>|null */
	public static function load_config(): ?array {
		$file = self::config_file();
		if ( ! is_file( $file ) ) {
			return null;
		}

		$config = include $file;
		if ( ! is_array( $config ) || self::CONFIG_VERSION !== ( $config['version'] ?? null ) ) {
			return null;
		}
		foreach ( array( 'base', 'prefix', 'uploads_path', 'uploads_dir' ) as $key ) {
			if ( ! isset( $config[ $key ] ) || ! is_string( $config[ $key ] ) ) {
				return null;
			}
		}

		return $config;
	}

	/** Entry point of proxy.php. */
	public static function handle_request(): void {
		$config = self::load_config();
		if ( null === $config || 'proxy' !== ( $config['mode'] ?? '' ) ) {
			self::plain( 404, 'Not Found' );
		}

		$relative = self::relative_from_request( (string) ( $_SERVER['REQUEST_URI'] ?? '' ), (string) $config['uploads_path'] );
		if ( null === $relative ) {
			self::plain( 404, 'Not Found' );
		}

		self::serve( $config, $relative );
	}

	/** Uploads-relative media path of a request URI, or null. */
	public static function relative_from_request( string $uri, string $uploads_path ): ?string {
		$path = (string) parse_url( $uri, PHP_URL_PATH );
		$base = rtrim( $uploads_path, '/' ) . '/';
		if ( '' === $path || ! str_starts_with( $path, $base ) ) {
			return null;
		}

		$relative = rawurldecode( substr( $path, strlen( $base ) ) );
		// No file name of the Media Library holds a control character (an encoded line break).
		if ( preg_match( '/[\x00-\x1F\x7F]/', $relative ) ) {
			return null;
		}

		return self::is_media_path( $relative ) ? $relative : null;
	}

	/** Same rule as Simple_Storage_Paths::is_media_path(), without WordPress. */
	public static function is_media_path( string $relative ): bool {
		if ( ! preg_match( '#^[0-9]{4}/[0-9]{2}/.+#', $relative ) || str_contains( $relative, "\0" ) || str_contains( $relative, '\\' ) || str_contains( $relative, '//' ) || str_ends_with( $relative, '/' ) ) {
			return false;
		}
		foreach ( explode( '/', $relative ) as $segment ) {
			if ( '' === $segment || '.' === $segment[0] ) {
				return false;
			}
		}

		return true;
	}

	/** Whether any part of a file name is the extension of a file a web server can run. */
	public static function is_code_file( string $relative ): bool {
		$parts = explode( '.', strtolower( substr( (string) strrchr( '/' . $relative, '/' ), 1 ) ) );
		array_shift( $parts );

		return ! empty( array_intersect( $parts, self::CODE_EXTENSIONS ) );
	}

	/**
	 * Send the file: from disk when it is (again) local, otherwise streamed from the storage.
	 *
	 * @param array<string, mixed> $config
	 */
	public static function serve( array $config, string $relative ): void {
		$method = strtoupper( (string) ( $_SERVER['REQUEST_METHOD'] ?? 'GET' ) );
		if ( 'GET' !== $method && 'HEAD' !== $method ) {
			header( 'Allow: GET, HEAD' );
			self::plain( 405, 'Method Not Allowed' );
		}
		if ( self::is_code_file( $relative ) ) {
			self::plain( 404, 'Not Found' );
		}

		self::reset_output();

		$local = rtrim( (string) $config['uploads_dir'], '/' ) . '/' . $relative;
		if ( is_file( $local ) ) {
			self::send_local( $config, $local, 'HEAD' === $method );
		}

		$url = rtrim( (string) $config['base'], '/' ) . '/' . self::encode( (string) $config['prefix'] ) . '/' . self::encode( $relative );
		self::stream( $config, $url, $relative, 'HEAD' === $method );
	}

	/** @param array<string, mixed> $config */
	private static function stream( array $config, string $url, string $relative, bool $head ): void {
		if ( ! function_exists( 'curl_init' ) ) {
			self::plain( 502, 'Bad Gateway' );
		}

		$request = array();
		foreach ( array(
			'HTTP_RANGE'             => 'Range',
			'HTTP_IF_RANGE'          => 'If-Range',
			'HTTP_IF_NONE_MATCH'     => 'If-None-Match',
			'HTTP_IF_MODIFIED_SINCE' => 'If-Modified-Since',
		) as $key => $name ) {
			if ( isset( $_SERVER[ $key ] ) && '' !== $_SERVER[ $key ] ) {
				$request[] = $name . ': ' . str_replace( array( "\r", "\n" ), '', (string) $_SERVER[ $key ] );
			}
		}

		for ( $hop = 0; $hop <= self::MAX_REDIRECTS; $hop++ ) {
			$status   = 0;
			$upstream = array();
			$started  = false;
			$rejected = false;

			$curl = curl_init( $url );
			curl_setopt_array(
				$curl,
				array(
					CURLOPT_HTTPHEADER      => $request,
					CURLOPT_NOBODY          => $head,
					// Followed by hand: a redirect of the storage must not reach the site's own network.
					CURLOPT_FOLLOWLOCATION  => false,
					CURLOPT_PROTOCOLS       => CURLPROTO_HTTP | CURLPROTO_HTTPS,
					CURLOPT_CONNECTTIMEOUT  => 10,
					CURLOPT_LOW_SPEED_LIMIT => 1,
					CURLOPT_LOW_SPEED_TIME  => 60,
					CURLOPT_USERAGENT       => 'SimpleStorage-Proxy',
					CURLOPT_HEADERFUNCTION  => static function ( $ch, string $line ) use ( &$status, &$upstream ): int {
						if ( preg_match( '#^HTTP/\S+\s+(\d{3})#', $line, $match ) ) {
							$status   = (int) $match[1];
							$upstream = array();
						} else {
							$parts = explode( ':', $line, 2 );
							if ( 2 === count( $parts ) ) {
								$upstream[ strtolower( trim( $parts[0] ) ) ] = trim( $parts[1] );
							}
						}

						return strlen( $line );
					},
					CURLOPT_WRITEFUNCTION   => static function ( $ch, string $chunk ) use ( &$started, &$rejected, &$status, &$upstream, $config, $relative ): int {
						if ( ! $started ) {
							if ( ! self::send_headers( $config, $relative, $status, $upstream ) ) {
								// An error page of the storage is not passed through; stop reading it.
								$rejected = true;

								return 0;
							}
							$started = true;
						}
						echo $chunk; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Binary file contents.
						flush();

						return connection_aborted() ? 0 : strlen( $chunk );
					},
				)
			);

			$result = curl_exec( $curl );

			if ( $started ) {
				// The body was streamed; a broken transfer can only be cut short at this point.
				exit;
			}

			$next = self::redirect_target( $url, $status, (string) ( $upstream['location'] ?? '' ) );
			if ( null === $next ) {
				break;
			}
			$url = $next;
		}

		if ( ! $rejected && false !== $result && 0 !== $status && self::send_headers( $config, $relative, $status, $upstream ) ) {
			// HEAD, 304 or an empty file: headers only.
			exit;
		}
		if ( in_array( $status, array( 403, 404, 410 ), true ) ) {
			self::plain( 404, 'Not Found' );
		}

		self::plain( 502, 'Bad Gateway' );
	}

	/**
	 * Where a redirect of the storage may lead: its own host or a public address, never the
	 * network of the site itself.
	 */
	private static function redirect_target( string $from, int $status, string $location ): ?string {
		if ( '' === $location || ! in_array( $status, array( 301, 302, 303, 307, 308 ), true ) ) {
			return null;
		}

		$base   = (array) parse_url( $from );
		$origin = ( $base['scheme'] ?? 'https' ) . '://' . ( $base['host'] ?? '' ) . ( isset( $base['port'] ) ? ':' . $base['port'] : '' );
		if ( str_starts_with( $location, '//' ) ) {
			$location = ( $base['scheme'] ?? 'https' ) . ':' . $location;
		} elseif ( str_starts_with( $location, '/' ) ) {
			$location = $origin . $location;
		}

		$target = (array) parse_url( $location );
		$host   = strtolower( (string) ( $target['host'] ?? '' ) );
		if ( '' === $host || ! in_array( strtolower( (string) ( $target['scheme'] ?? '' ) ), array( 'http', 'https' ), true ) ) {
			return null;
		}
		if ( strtolower( (string) ( $base['host'] ?? '' ) ) === $host ) {
			return $location;
		}

		return false !== filter_var( gethostbyname( $host ), FILTER_VALIDATE_IP, FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE ) ? $location : null;
	}

	/**
	 * Headers for a storage response; false when the response must not be passed through.
	 *
	 * @param array<string, mixed>  $config
	 * @param array<string, string> $upstream
	 */
	private static function send_headers( array $config, string $relative, int $status, array $upstream ): bool {
		if ( ! in_array( $status, array( 200, 206, 304, 416 ), true ) ) {
			return false;
		}

		http_response_code( $status );
		self::type_headers( $relative );
		foreach ( array( 'content-length' => 'Content-Length', 'content-range' => 'Content-Range', 'etag' => 'ETag', 'last-modified' => 'Last-Modified' ) as $key => $name ) {
			if ( isset( $upstream[ $key ] ) ) {
				header( $name . ': ' . $upstream[ $key ] );
			}
		}
		header( 'Accept-Ranges: bytes' );
		// A range outside the file says something about one request only: nothing may keep it.
		self::common_headers( 416 === $status ? array( 'cache_control' => 'no-store' ) : $config );

		return true;
	}

	/** @param array<string, mixed> $config */
	private static function send_local( array $config, string $file, bool $head ): void {
		$size  = (int) filesize( $file );
		$mtime = (int) filemtime( $file );
		$etag  = '"' . dechex( $mtime ) . '-' . dechex( $size ) . '"';

		self::type_headers( $file );
		header( 'Last-Modified: ' . gmdate( 'D, d M Y H:i:s', $mtime ) . ' GMT' );
		header( 'ETag: ' . $etag );
		self::common_headers( $config );

		if ( trim( (string) ( $_SERVER['HTTP_IF_NONE_MATCH'] ?? '' ) ) === $etag ) {
			http_response_code( 304 );
			exit;
		}

		http_response_code( 200 );
		header( 'Content-Length: ' . $size );
		if ( ! $head ) {
			readfile( $file ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_readfile
		}
		exit;
	}

	/** @param array<string, mixed> $config */
	private static function common_headers( array $config ): void {
		$cache = (string) ( $config['cache_control'] ?? '' );
		if ( '' !== $cache ) {
			header( 'Cache-Control: ' . $cache );
		}
		header( 'X-Content-Type-Options: nosniff' );
		header( 'X-Simple-Storage: proxy' );
	}

	/**
	 * The type comes from the extension and never from the storage: whoever can write to the
	 * storage must not decide what runs under the site address. Other files are downloads, and an
	 * SVG opened on its own runs no script.
	 */
	private static function type_headers( string $path ): void {
		$extension = strtolower( (string) pathinfo( $path, PATHINFO_EXTENSION ) );
		if ( isset( self::TYPES[ $extension ] ) ) {
			header( 'Content-Type: ' . self::TYPES[ $extension ] );
		} else {
			header( 'Content-Type: application/octet-stream' );
			header( 'Content-Disposition: attachment' );
		}
		if ( 'svg' === $extension ) {
			header( "Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; sandbox" );
		}
	}

	private static function encode( string $path ): string {
		return implode( '/', array_map( 'rawurlencode', explode( '/', $path ) ) );
	}

	/** Drop buffers and compression so that large files stream with constant memory. */
	private static function reset_output(): void {
		@ini_set( 'zlib.output_compression', 'Off' ); // phpcs:ignore WordPress.PHP.NoSilencedErrors.Discouraged, WordPress.PHP.IniSet.Risky
		while ( ob_get_level() > 0 ) {
			ob_end_clean();
		}
		if ( function_exists( 'set_time_limit' ) ) {
			@set_time_limit( 0 ); // phpcs:ignore WordPress.PHP.NoSilencedErrors.Discouraged
		}
		if ( function_exists( 'header_remove' ) && ! headers_sent() ) {
			header_remove( 'Set-Cookie' );
			header_remove( 'Cache-Control' );
			header_remove( 'Expires' );
			header_remove( 'Pragma' );
		}
	}

	private static function plain( int $status, string $message ): void {
		if ( ! headers_sent() ) {
			http_response_code( $status );
			header( 'Content-Type: text/plain; charset=utf-8' );
			header( 'Cache-Control: no-store' );
			// Its own answers tell the serving diagnosis that proxy.php runs.
			header( 'X-Simple-Storage: proxy' );
		}
		echo $message; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Fixed plain-text status line.
		exit;
	}

	/**
	 * PHP source of the configuration file.
	 *
	 * @param array<string, mixed> $config
	 */
	public static function config_source( array $config ): string {
		$config['version'] = self::CONFIG_VERSION;

		return "<?php\n// " . self::CONFIG_MARKER . ". Do not edit: the plugin rewrites this file.\n// It holds no credentials, only where the media are served from.\nreturn " . var_export( $config, true ) . ";\n"; // phpcs:ignore WordPress.PHP.DevelopmentFunctions.error_log_var_export
	}
}
